package session

import (
	"fmt"

	"github.com/jeremyhahn/go-libsignal/pkg/util/crypto"
	"github.com/jeremyhahn/go-libsignal/pkg/util/crypto/secret"
)

// secretAlloc is the function used to allocate guarded secrets. It defaults to
// secret.New and may be replaced in tests to simulate allocation failures.
var secretAlloc = secret.New

// NewDerivedSecrets returns a new RootKey/ChainKey/InitialPQRKey triple from 96 bytes
// of key material generated by the key derivation function. Each 32-byte segment is
// moved into locked memory. The source keyMaterial slice is zeroized after
// splitting. Panics if locked-memory allocation fails (fatal condition).
//
// This matches the Rust derive_keys which returns (RootKey, ChainKey, InitialPQRKey).
func NewDerivedSecrets(keyMaterial []byte) *DerivedSecrets {
	rootKeyBytes := make([]byte, 32)
	chainKeyBytes := make([]byte, 32)
	copy(rootKeyBytes, keyMaterial[:32])
	copy(chainKeyBytes, keyMaterial[32:64])

	// Extract the third 32-byte segment for the InitialPQRKey if present.
	var pqrKeyBytes []byte
	if len(keyMaterial) >= 96 {
		pqrKeyBytes = make([]byte, 32)
		copy(pqrKeyBytes, keyMaterial[64:96])
	}
	crypto.Zeroize(keyMaterial)

	guardedRoot, err := secretAlloc(rootKeyBytes)
	if err != nil {
		panic("session: failed to allocate guarded memory for root key: " + err.Error())
	}
	guardedChain, err := secretAlloc(chainKeyBytes)
	if err != nil {
		guardedRoot.Destroy()
		panic("session: failed to allocate guarded memory for chain key: " + err.Error())
	}

	var guardedPQR *secret.Secret
	if pqrKeyBytes != nil {
		guardedPQR, err = secretAlloc(pqrKeyBytes)
		if err != nil {
			guardedRoot.Destroy()
			guardedChain.Destroy()
			panic("session: failed to allocate guarded memory for PQR key: " + err.Error())
		}
	}

	return &DerivedSecrets{
		rootKey:  guardedRoot,
		chainKey: guardedChain,
		pqrKey:   guardedPQR,
	}
}

// DerivedSecrets is a structure for holding the derived secrets for the
// Root, Chain, and InitialPQR keys for a session. Key material is stored in
// locked memory.
type DerivedSecrets struct {
	rootKey  *secret.Secret
	chainKey *secret.Secret
	pqrKey   *secret.Secret
}

// derivedKeyLength is the length of each derived key.
const derivedKeyLength = 32

// KeyLengthError indicates that a derived key was missing, or held the
// wrong number of bytes, when it was copied out of guarded memory. A
// missing, short or long key is refused rather than used.
type KeyLengthError struct {
	Field string
	Got   int
	Want  int
}

func (e *KeyLengthError) Error() string {
	return fmt.Sprintf("session: %s is %d bytes, want %d", e.Field, e.Got, e.Want)
}

// RootKey returns a copy of the RootKey bytes, made inside a WithBytes
// borrow of the guarded memory. A missing, destroyed or wrong-length key is
// an error. The caller should wipe it after use.
func (d *DerivedSecrets) RootKey() ([]byte, error) {
	return copySecret(d.rootKey, "root key")
}

// ChainKey returns a copy of the ChainKey bytes, made inside a WithBytes
// borrow of the guarded memory. A missing, destroyed or wrong-length key is
// an error. The caller should wipe it after use.
func (d *DerivedSecrets) ChainKey() ([]byte, error) {
	return copySecret(d.chainKey, "chain key")
}

// InitialPQRKey returns a copy of the InitialPQRKey bytes, made inside a
// WithBytes borrow, or nil, nil if no PQR key was derived (e.g., for legacy
// 64-byte derivations). A destroyed or wrong-length key is an error, so it
// is never mistaken for a session without PQR. The caller should wipe it
// after use.
func (d *DerivedSecrets) InitialPQRKey() ([]byte, error) {
	if d.pqrKey == nil {
		return nil, nil
	}
	return copySecret(d.pqrKey, "initial PQR key")
}

// copySecret copies the material of s out inside a WithBytes borrow. The
// material must be exactly derivedKeyLength bytes; a nil, destroyed or
// wrong-length secret is an error, never a nil or short copy.
func copySecret(s *secret.Secret, field string) ([]byte, error) {
	if s == nil {
		return nil, &KeyLengthError{Field: field, Want: derivedKeyLength}
	}
	var out []byte
	if err := s.WithBytes(func(b []byte) error {
		if len(b) != derivedKeyLength {
			return &KeyLengthError{Field: field, Got: len(b), Want: derivedKeyLength}
		}
		out = append(make([]byte, 0, derivedKeyLength), b...)
		return nil
	}); err != nil {
		return nil, err
	}
	return out, nil
}

// Zeroize destroys the guarded memory holding the derived secrets.
// This method is idempotent and safe to call multiple times.
func (d *DerivedSecrets) Zeroize() {
	if d.rootKey != nil {
		d.rootKey.Destroy()
	}
	if d.chainKey != nil {
		d.chainKey.Destroy()
	}
	if d.pqrKey != nil {
		d.pqrKey.Destroy()
	}
}
